import json
S = []
def n(scene, text, kick=None, **p): S.append({"scene": scene, "text": text, "spk": "n", "kick": kick, "params": p})
def card(num, title): S.append({"scene": "chapter", "text": None, "kick": None, "params": {"num": num, "title": title}, "dur": 3.0})
n("hookQ", "Everyone's asking whether Nvidia's CEO had an affair with a spy.", None, mode="gossip", disclaimer=True)
n("hookQ", "Here's the question Washington should have to answer. Who got warned? When did they know? And why did the chips keep moving?", None, mode="questions")
n("coldOpen", "On November 8th, Jensen Huang, the founder of Nvidia, told his employees he had been unfaithful to his wife. He didn't name the woman.", "NOVEMBER 8", mode="message")
n("coldOpen", "The New York Times did. It identified her as Alice Huang, a Chinese businesswoman and former executive at Megaspeed, a Singapore company that bought Nvidia chips. No relation to Jensen.", "THE NEW YORK TIMES REPORTED", mode="report")
n("coldOpen", "Four days later, Jensen Huang was no longer Nvidia's CEO. But the bigger story may not be about him at all. It may be about what Washington knew, and when.", "THE BIGGER STORY", mode="washington")
card(1, "THE MAN WITH THE KEY")
n("ceoBio", "To see why this matters, you need to understand what Jensen Huang built. He was born in Taiwan, sent to the United States as a child, and ended up at a strict boarding school in rural Kentucky. Later, he worked at Denny's, waiting tables and washing dishes.", "FROM DISHWASHER", step=0)
n("ceoBio", "In 1993, he and two engineers started a company to make graphics chips. They called it Nvidia. It nearly died. Huang has said that in 1997, the company was about a month away from going out of business.", "NVIDIA, 1993", step=1)
n("cooks", "What saved it was a simple idea. A normal processor is like one brilliant chef, cooking every dish one at a time. Nvidia's chips are like thousands of cooks, each flipping a pancake at the same moment.", "THOUSANDS OF COOKS")
n("cooks", "That was perfect for video games. And it turned out to be perfect for artificial intelligence, which needs the same kind of math done billions of times over.", "PERFECT FOR AI", mode="ai")
n("stockRise", "When the AI boom arrived, almost everyone building it needed Nvidia's chips. Nvidia became one of the most valuable companies on Earth, and its chips became the most wanted hardware in the world.", "THE MOST WANTED CHIPS")
card(2, "THE LOCKED DOOR")
n("exportBan", "Then Washington changed the locks. In October 2022, the United States restricted exports of its most advanced AI chips to China, to slow China's progress in artificial intelligence and military technology.", "OCTOBER 2022: EXPORT CONTROLS")
n("exportBan", "For Nvidia, China had been a huge market. Huang later said Nvidia's share of China's AI chip market went from about 95 percent to nearly zero.", "95% TO NEARLY ZERO", mode="share")
n("policySwing", "And the rules kept moving. Some chips were blocked, then allowed again under special arrangements. Huang became one of the loudest voices arguing that blocking American chips would only push China to build its own.", "THE RULES KEPT MOVING")
n("scale", "That's the tension at the heart of this story. Washington wanted two things at once: to sell the world American AI, and to keep the best of it away from China.", "TWO GOALS AT ONCE")
card(3, "THE WORKAROUND")
n("workaround", "When a door is locked, people look for windows. Some tried crude smuggling, routing chips through other countries, and some have been caught and charged.", "SMUGGLING", mode="smuggle")
n("workaround", "But there's a quieter route. Export rules focus on where chips are shipped. So a company outside China can buy the chips, keep them in a data center nearby, and rent the computing power over the internet. The chips never move. The work does.", "THE CLOUD ROUTE", mode="cloud")
n("megaspeed", "Megaspeed, the Singapore company where Alice Huang had been an executive, came under scrutiny over suspected diversion of restricted Nvidia chips to China. U.S. senators cited reports that the Justice Department was investigating whether Megaspeed broke export rules.", "UNDER SCRUTINY")
card(4, "THE WARNINGS")
n("warnings", "Here's where the story turns. U.S. officials were reportedly warned about Jensen Huang's relationship with Alice Huang before the scandal became public.", "REPORTEDLY WARNED", mode="memo")
n("warnings", "The New York Times reported that U.S. intelligence had concluded she was passing information to Beijing.", "THE NEW YORK TIMES REPORTED", mode="intel")
n("warnings", "And yet, according to reports, chip shipments to companies linked to her continued.", "THE CHIPS KEPT MOVING", mode="trucks")
n("senators", "Now U.S. senators are asking what officials knew, and why those shipments went on. Who received the warnings? Who decided what to do with them? And did the push to sell American chips win out over the security concerns?", "SENATORS ARE ASKING")
card(5, "FOUR DAYS IN NOVEMBER")
n("calendar", "Here's how it unfolded. November 8th: Huang admits the affair, and Nvidia's board opens an independent investigation into whether its CEO had been targeted by a foreign intelligence operation.", "NOVEMBER 8", day=0)
n("calendar", "November 10th: The Information, as reported by Reuters, alleges that Alice Huang used her ties to Nvidia and its distributors to help move roughly 240,000 chips, worth at least seven and a half billion dollars, into China.", "NOVEMBER 10", day=1)
n("chips7", "That figure comes from investigative reporting. It has not been proven in court.", "ALLEGED, NOT PROVEN")
n("calendar", "November 12th: Nvidia announces that Jensen Huang has resigned as CEO and left the board. Its chief financial officer, Colette Kress, becomes interim CEO.", "NOVEMBER 12", day=2)
n("resignation", "When the board opened its inquiry, it said it had no reason at that point to believe Nvidia's secrets or U.S. national security had been compromised. The man who started Nvidia in a diner booth was gone in four days.", "THE BOARD'S POSITION")
card(6, "TWO QUESTIONS")
n("intelSplit", "So, was she a spy? That's still unresolved. The New York Times reported U.S. intelligence believed she passed information to Beijing. CNN later reported that officials disagreed on whether she did it knowingly. The attorney general said the Justice Department had reached no conclusion about her role. And China's Foreign Ministry rejected the allegation.", "STILL UNRESOLVED")
n("twoQuestions", "But notice there are really two separate questions. Did she knowingly work for Beijing? And how did Washington handle the warnings it reportedly received? The first one may take years to answer. The second one stands either way.", "TWO SEPARATE QUESTIONS")
n("scale", "Because if warnings were raised and the chips kept moving, the question isn't just about one woman, or one CEO. It's about whether the AI chip business was put ahead of the security warnings meant to protect it.", "BUSINESS VS SECURITY", mode="tip")
n("cta", "So who should have warned him, and who should answer for it? Tell me in the comments. And subscribe if you want the next story like this.", "WHO SHOULD ANSWER?")
S.append({"scene": "endcard", "text": None, "kick": None, "params": {}, "dur": 7.0})
json.dump(S, open("segments.json", "w"), indent=1)
print(len(S), "segments,", sum(len(s["text"].split()) for s in S if s["text"]), "words")
